import Foundation
import AppKit
import Combine
import SQLite3
import KatibCore

/// Lightweight clipboard history — text only, ring-buffered, JSON-persisted.
///
/// Architecture cribbed from Maccy's Clipboard.swift:
/// - Poll NSPasteboard.changeCount every 1s (no event API exists on macOS).
/// - Ignore pasteboard types that indicate the source doesn't want history:
///   .concealed (password managers), .transient (auto-clearing), .autoGenerated.
/// - Write a private marker type on Katib's own dictation paste and skip
///   anything that carries it — otherwise the watcher re-captures Katib's
///   output as if the user copied it.
///
/// Privacy:
/// - Text only for v1. No images, no files — reduces disk size and scrubs
///   most accidental capture of binary secrets.
/// - Default cap: 20 items. Configurable in Settings (future).
/// - Persisted to ~/Library/Application Support/VoiceTools/clipboard-history.json.
///   Survives relaunch. "Clear history" wipes it.
/// - `clipboardEnabled` in AppSettings defaults OFF — opt-in.
@MainActor
public final class ClipboardManager: ObservableObject {
    public static let shared = ClipboardManager()

    @Published public private(set) var items: [ClipboardItem] = []

    /// Toggled by `AppSettings.clipboardEnabled` observation in the app shell,
    /// or directly from tests. Module boundary → public.
    public var isEnabled: Bool {
        didSet { isEnabled ? start() : stop() }
    }

    /// Backing storage so init can set capacity WITHOUT firing the
    /// trim+persist side effects. `var capacity { didSet { … persist() } }`
    /// would persist an empty `items` array during init (before
    /// loadFromDisk runs) and destroy the file. Backing-store + computed
    /// property lets init use `_capacity = …` directly.
    private var _capacity: Int = 20
    public var capacity: Int {
        get { _capacity }
        set {
            guard _capacity != newValue else { return }
            _capacity = newValue
            trimToCapacity()
            persist()
        }
    }

    /// Pure: would persisting a load-time trim cost the user more than
    /// half of their on-disk items? Used by `loadFromDisk` as a circuit
    /// breaker against init-order bugs (capacity not yet pulled from
    /// settings ⇒ default value ⇒ destroys the file). Public + static so
    /// the test suite can lock the threshold down.
    public static func loadSafetyTripped(loadedCount: Int, postTrimCount: Int) -> Bool {
        guard loadedCount > 0 else { return false }
        return Double(postTrimCount) / Double(loadedCount) < 0.5
    }

    /// Per-item lowercased search cache. At 8000+ items,
    /// `item.text.lowercased()` on every keystroke dominated the filter —
    /// one Unicode normalization + allocation per item per key. Cached
    /// by item.id so we lowercase once per clip and reuse. Cleared
    /// whenever items mutates (append/remove/clear/trim all invalidate).
    private var searchLowerCache: [UUID: String] = [:]

    private func lowerFor(_ item: ClipboardItem) -> String {
        if let cached = searchLowerCache[item.id] { return cached }
        let lower = item.text.lowercased()
        searchLowerCache[item.id] = lower
        return lower
    }

    /// Items filtered + ordered for UI display: pinned first, then recency.
    /// `imagesOnly` filters to image clips only; orthogonal to the text
    /// search query (which still applies to image item descriptions if
    /// they happen to be set, though most are empty).
    public func visibleItems(matching query: String, imagesOnly: Bool = false) -> [ClipboardItem] {
        let q = query.trimmingCharacters(in: .whitespaces).lowercased()
        // Single pass: walk the array once, partition into pinned vs
        // unpinned. Was 3× passes before (filter-pinned, filter-unpinned,
        // each iterating the full 8k array). Same result, ~3× faster.
        var pins: [ClipboardItem] = []
        var unpinned: [ClipboardItem] = []
        pins.reserveCapacity(16)
        unpinned.reserveCapacity(items.count)
        for item in items {
            if imagesOnly && item.image == nil { continue }
            if !q.isEmpty && !Self.utf8Contains(lowerFor(item), q) { continue }
            if item.pinned { pins.append(item) } else { unpinned.append(item) }
        }
        return pins + unpinned
    }

    /// Substring test on UTF-8 bytes (memmem). Both sides are already
    /// lowercased; `String.contains` does Unicode-aware comparison, which was
    /// most of the per-keystroke cost on a 20k-clip history.
    nonisolated static func utf8Contains(_ haystack: String, _ needle: String) -> Bool {
        if needle.isEmpty { return true }
        var hay = haystack
        var nee = needle
        return hay.withUTF8 { h in
            nee.withUTF8 { n in
                guard n.count <= h.count else { return false }
                guard let hb = h.baseAddress, let nb = n.baseAddress else { return false }
                return memmem(hb, h.count, nb, n.count) != nil
            }
        }
    }

    public func togglePin(_ item: ClipboardItem) {
        guard let idx = items.firstIndex(where: { $0.id == item.id }) else { return }
        items[idx].pinned.toggle()
        persist()
    }

    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?
    // `var` (not `let`) so `_useIsolatedTestStore()` can redirect the
    // singleton to a temp folder during tests. Production code reads
    // these once in init and never modifies them.
    private var storeURL: URL
    private var imagesFolderURL: URL
    private let maxBytesPerItem = 1_000_000 // 1 MB text
    private let maxImageBytes = 10_000_000 // 10 MB
    private let ignoredTypes: Set<NSPasteboard.PasteboardType> = [
        .init("org.nspasteboard.ConcealedType"),
        .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"),
        KatibPasteboard.katibMarkerType
    ]

    /// Bundle IDs whose copies we never capture. Prepopulated with well-known
    /// secret holders (Alfred + Raycast both ship a similar baseline).
    public static let defaultIgnoredBundles: Set<String> = [
        "com.apple.keychainaccess",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword4",
        "com.1password.1password",
        "com.1password.1password-launcher",
        "com.bitwarden.desktop",
        "com.dashlane.DashlanePhoneFinalMac",
        "com.lastpass.LastPass",
        "com.enpass.Enpass-Desktop"
    ]

    public var ignoredBundles: Set<String> {
        get {
            if let stored = UserDefaults.standard.stringArray(forKey: "clipboardIgnoredBundles") {
                return Set(stored)
            }
            return Self.defaultIgnoredBundles
        }
        set {
            UserDefaults.standard.set(Array(newValue), forKey: "clipboardIgnoredBundles")
        }
    }

    private init() {
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
        let folder = appSupport.appendingPathComponent("VoiceTools", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        storeURL = folder.appendingPathComponent("clipboard-history.json")
        imagesFolderURL = folder.appendingPathComponent("clipboard-images", isDirectory: true)
        try? FileManager.default.createDirectory(at: imagesFolderURL, withIntermediateDirectories: true)
        lastChangeCount = NSPasteboard.general.changeCount
        self.isEnabled = AppSettings.shared.clipboardEnabled

        // Read capacity from settings BEFORE loadFromDisk. Direct assignment
        // to `_capacity` (backing store) so the computed property's
        // `set { … persist() }` doesn't fire — that persist would write
        // an empty items array to disk before loadFromDisk could run.
        _capacity = AppSettings.shared.clipboardCapacity

        loadFromDisk()
        if isEnabled { start() }
    }

    /// TEST-ONLY: redirect the singleton's persistence to an isolated
    /// temporary folder so tests can call `clear()` / `append` without
    /// touching the user's real `~/Library/Application Support/VoiceTools/`
    /// store. **Catastrophic bug history**: before this existed, every
    /// `swift test` invocation wiped the production clipboard file via
    /// `ClipboardManager.shared.clear()` in test setUp. Pre-commit hooks +
    /// CI runs were silently destroying the user's data.
    ///
    /// Call once in test target setUp. Production must NEVER call this.
    // swiftlint:disable:next identifier_name
    internal func _useIsolatedTestStore() {
        let tmp = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("KatibTests-\(UUID().uuidString)", isDirectory: true)
        try? FileManager.default.createDirectory(at: tmp, withIntermediateDirectories: true)
        storeURL = tmp.appendingPathComponent("clipboard-history.json")
        imagesFolderURL = tmp.appendingPathComponent("clipboard-images", isDirectory: true)
        try? FileManager.default.createDirectory(at: imagesFolderURL, withIntermediateDirectories: true)
        items = []  // start clean — no persist call needed
    }

    /// Test-only: replace the history in memory (no persist) and start with
    /// a cold search cache. Used by the search benchmark.
    // swiftlint:disable:next identifier_name
    internal func _setItemsForTesting(_ newItems: [ClipboardItem]) {
        items = newItems
        searchLowerCache.removeAll()
    }

    /// Full path for an image sidecar file.
    public func imageURL(for image: ClipboardImage) -> URL {
        imagesFolderURL.appendingPathComponent(image.filename)
    }

    private func start() {
        guard timer == nil else { return }
        lastChangeCount = pasteboard.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.poll() }
        }
        Logger.shared.log("Clipboard watcher started")
    }

    private func stop() {
        timer?.invalidate()
        timer = nil
        Logger.shared.log("Clipboard watcher stopped")
    }

    private func poll() {
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount

        // Skip if source marked the clip as private / transient / our own.
        let types = Set(pasteboard.types ?? [])
        if !types.isDisjoint(with: ignoredTypes) { return }

        // Skip if the frontmost app is on the ignore list (password managers
        // usually copy via their own UI — this catches anything that doesn't
        // mark its pasteboard as concealed).
        if let bundleID = NSWorkspace.shared.frontmostApplication?.bundleIdentifier,
           ignoredBundles.contains(bundleID) {
            return
        }

        let frontmost = NSWorkspace.shared.frontmostApplication
        let sourceApp = frontmost?.localizedName
        let sourceBundleID = frontmost?.bundleIdentifier

        // Prefer text — most clips are text, and some apps put both text and
        // image on the pasteboard when copying a PDF/doc selection.
        if let string = pasteboard.string(forType: .string) {
            let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                guard trimmed.utf8.count <= maxBytesPerItem else {
                    Logger.shared.log("Clipboard: rejected oversized text clip (\(trimmed.utf8.count) bytes)")
                    return
                }
                append(trimmed, sourceApp: sourceApp, sourceBundleID: sourceBundleID)
                evictExpiredItems()
                return
            }
        }

        // Image fallback.
        if let (data, size) = imageData(from: pasteboard) {
            guard data.count <= maxImageBytes else {
                Logger.shared.log("Clipboard: rejected oversized image (\(data.count) bytes)")
                return
            }
            appendImage(data: data, size: size, sourceApp: sourceApp, sourceBundleID: sourceBundleID)
            evictExpiredItems()
        }
    }

    private func imageData(from pb: NSPasteboard) -> (Data, CGSize)? {
        if let png = pb.data(forType: .png), let size = sizeOf(data: png) {
            return (png, size)
        }
        if let tiff = pb.data(forType: .tiff),
           let rep = NSBitmapImageRep(data: tiff),
           let png = rep.representation(using: .png, properties: [:]) {
            return (png, CGSize(width: rep.pixelsWide, height: rep.pixelsHigh))
        }
        return nil
    }

    private func sizeOf(data: Data) -> CGSize? {
        guard let rep = NSBitmapImageRep(data: data) else { return nil }
        return CGSize(width: rep.pixelsWide, height: rep.pixelsHigh)
    }

    /// Record a screenshot (or any captured image) into the clipboard
    /// history. Public entry point so ScreenshotManager can persist
    /// captures alongside text clips. Image bytes get written to the
    /// sidecar folder + a thumbnail goes into the JSON store.
    public func recordCapturedImage(pngData: Data, width: Int, height: Int, sourceApp: String? = nil) {
        appendImage(data: pngData, size: CGSize(width: width, height: height),
                    sourceApp: sourceApp ?? "Katib screenshot")
    }

    private func appendImage(data: Data, size: CGSize, sourceApp: String?, sourceBundleID: String? = nil) {
        let filename = "\(UUID().uuidString).png"
        let url = imagesFolderURL.appendingPathComponent(filename)
        do {
            try data.write(to: url, options: .atomic)
        } catch {
            Logger.shared.log("Clipboard: failed to write image sidecar — \(error)")
            return
        }

        let thumbnail = Self.makeThumbnail(data: data, maxDimension: 128) ?? Data()
        let image = ClipboardImage(
            filename: filename,
            width: Int(size.width),
            height: Int(size.height),
            bytes: data.count,
            thumbnail: thumbnail
        )
        let item = ClipboardItem(
            id: UUID(),
            text: "",
            capturedAt: Date(),
            pinned: false,
            sourceApp: sourceApp,
            sourceBundleID: sourceBundleID,
            image: image
        )
        items.insert(item, at: 0)
        trimToCapacity()
        persist()
    }

    private static func makeThumbnail(data: Data, maxDimension: Int) -> Data? {
        guard let source = NSBitmapImageRep(data: data) else { return nil }
        let scale = min(
            CGFloat(maxDimension) / CGFloat(source.pixelsWide),
            CGFloat(maxDimension) / CGFloat(source.pixelsHigh),
            1.0
        )
        if scale >= 1.0 {
            return source.representation(using: .png, properties: [:])
        }
        let newWidth = Int(CGFloat(source.pixelsWide) * scale)
        let newHeight = Int(CGFloat(source.pixelsHigh) * scale)
        let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: newWidth, pixelsHigh: newHeight,
            bitsPerSample: 8, samplesPerPixel: 4,
            hasAlpha: true, isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0, bitsPerPixel: 32
        )
        guard let rep, let cgContext = NSGraphicsContext(bitmapImageRep: rep) else { return nil }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = cgContext
        source.draw(in: NSRect(x: 0, y: 0, width: newWidth, height: newHeight))
        NSGraphicsContext.restoreGraphicsState()
        return rep.representation(using: .png, properties: [:])
    }

    /// Push a captured string onto the ring, dedup + cap + persist. Pinned
    /// items are preserved and don't count against the unpinned capacity.
    public func append(_ text: String, sourceApp: String? = nil, sourceBundleID: String? = nil) {
        // If the item already exists: bump it to the top with a fresh
        // capturedAt and preserve pin state. Ignore image items (their text
        // is always empty, so they'd otherwise match every text dedup check).
        if let existingIdx = items.firstIndex(where: { $0.text == text && $0.image == nil }) {
            var updated = items[existingIdx]
            updated.capturedAt = Date()
            items.remove(at: existingIdx)
            items.insert(updated, at: 0)
        } else {
            let new = ClipboardItem(
                id: UUID(),
                text: text,
                capturedAt: Date(),
                pinned: false,
                sourceApp: sourceApp,
                sourceBundleID: sourceBundleID
            )
            items.insert(new, at: 0)
        }
        trimToCapacity()
        persist()
    }

    private func trimToCapacity() {
        let unpinnedIndices = items.enumerated().compactMap { idx, item in
            item.pinned ? nil : idx
        }
        let overflow = unpinnedIndices.count - capacity
        guard overflow > 0 else { return }
        // Drop the oldest unpinned items.
        let toDrop = Set(unpinnedIndices.suffix(overflow))
        items = items.enumerated()
            .filter { !toDrop.contains($0.offset) }
            .map(\.element)
        invalidateSearchCache()
    }

    /// Apply time-based retention — walk the ring, drop unpinned items older
    /// than the configured window. Pinned items are kept forever.
    public func evictExpiredItems() {
        let windowSeconds = AppSettings.shared.clipboardRetention.seconds
        guard windowSeconds > 0 else { return }
        let cutoff = Date().addingTimeInterval(-windowSeconds)
        let before = items.count
        items = items.filter { $0.pinned || $0.capturedAt >= cutoff }
        if items.count != before {
            invalidateSearchCache()
            persist()
        }
    }

    /// Copy an item to the pasteboard so the user can Cmd+V it into the
    /// frontmost app. We DON'T restore after — that's the point.
    public func copyToPasteboard(_ item: ClipboardItem) {
        pasteboard.clearContents()
        if let image = item.image,
           let data = try? Data(contentsOf: imageURL(for: image)) {
            pasteboard.setData(data, forType: .png)
            return
        }
        pasteboard.setString(item.text, forType: .string)
    }

    /// Copy as plain text — strips any styling that might be latent in the
    /// original (we only store strings, but a caller pasting from HTML/RTF
    /// source into Katib-captured text may still benefit). Collapses
    /// trailing whitespace. For image items, falls back to the regular copy.
    public func copyPlainToPasteboard(_ item: ClipboardItem) {
        guard item.image == nil else {
            copyToPasteboard(item)
            return
        }
        let cleaned = item.text.trimmingCharacters(in: .whitespacesAndNewlines)
        pasteboard.clearContents()
        pasteboard.setString(cleaned, forType: .string)
    }

    public func remove(_ item: ClipboardItem) {
        if let image = item.image {
            try? FileManager.default.removeItem(at: imageURL(for: image))
        }
        items.removeAll { $0.id == item.id }
        persist()
    }

    /// Drop cache entries for items that are gone. Called on every path that
    /// removes from `items`. It used to wipe the whole cache, and trim runs on
    /// every copy once history is full, so the first search after any copy
    /// re-lowercased all ~20k clips (some up to 1 MB). `text` is immutable,
    /// so an entry stays valid for as long as its item exists.
    private func invalidateSearchCache() {
        guard !searchLowerCache.isEmpty else { return }
        let live = Set(items.lazy.map(\.id))
        searchLowerCache = searchLowerCache.filter { live.contains($0.key) }
    }

    public func clear() {
        // Wipe image sidecars too so the disk footprint drops with the list.
        for item in items {
            if let image = item.image {
                try? FileManager.default.removeItem(at: imageURL(for: image))
            }
        }
        items = []
        invalidateSearchCache()
        persist()
        Logger.shared.log("Clipboard history cleared by user")
    }

    // MARK: - Alfred migration

    public struct AlfredImportResult {
        public let imported: Int
        public let skipped: Int
        public let errorMessage: String?
        public var didSucceed: Bool { errorMessage == nil }
    }

    /// Import the most recent `limit` text clips from Alfred's SQLite store.
    /// Text only (`dataType = 0` in Alfred). De-dupes against existing items
    /// by exact text match. Respects the current retention window — items
    /// older than the cutoff are skipped unless retention is unlimited.
    @discardableResult
    public func importFromAlfred(limit: Int) -> AlfredImportResult {
        let home = FileManager.default.homeDirectoryForCurrentUser
        let dbPath = home.appendingPathComponent(
            "Library/Application Support/Alfred/Databases/clipboard.alfdb"
        ).path

        Logger.shared.log("Alfred import: START. limit=\(limit), dbPath=\(dbPath)")

        let dbExists = FileManager.default.fileExists(atPath: dbPath)
        let dbAttrs = (try? FileManager.default.attributesOfItem(atPath: dbPath)) ?? [:]
        let dbSize = (dbAttrs[.size] as? Int) ?? -1
        Logger.shared.log("Alfred import: db exists=\(dbExists), size=\(dbSize) bytes")

        var db: OpaquePointer?
        let openStatus = sqlite3_open_v2(dbPath, &db, SQLITE_OPEN_READONLY, nil)
        guard openStatus == SQLITE_OK else {
            let errMsg = db.flatMap { String(cString: sqlite3_errmsg($0)) } ?? "no message"
            sqlite3_close(db)
            Logger.shared.log("Alfred import: FAILED to open db. status=\(openStatus) err=\(errMsg)")
            return AlfredImportResult(imported: 0, skipped: 0,
                                      errorMessage: "Couldn't open \(dbPath). \(errMsg)")
        }
        defer { sqlite3_close(db) }

        let sql = "SELECT item, ts, app FROM clipboard WHERE dataType = 0 ORDER BY ts DESC LIMIT ?"
        var stmt: OpaquePointer?
        let prepStatus = sqlite3_prepare_v2(db, sql, -1, &stmt, nil)
        guard prepStatus == SQLITE_OK else {
            let errMsg = String(cString: sqlite3_errmsg(db))
            Logger.shared.log("Alfred import: FAILED prepare. status=\(prepStatus) err=\(errMsg)")
            return AlfredImportResult(imported: 0, skipped: 0,
                                      errorMessage: "Alfred DB query failed: \(errMsg)")
        }
        defer { sqlite3_finalize(stmt) }
        sqlite3_bind_int(stmt, 1, Int32(limit))

        let retention = AppSettings.shared.clipboardRetention.seconds
        let cutoff = retention > 0 ? Date().addingTimeInterval(-retention) : .distantPast
        Logger.shared.log("Alfred import: retention=\(Int(retention))s cutoff=\(cutoff) existing items=\(items.count)")

        var existing = Set(items.map(\.text))
        var imported: [ClipboardItem] = []
        var skippedDup = 0
        var skippedRetention = 0
        var skippedEmpty = 0
        var rowsRead = 0

        while sqlite3_step(stmt) == SQLITE_ROW {
            rowsRead += 1
            guard let itemCStr = sqlite3_column_text(stmt, 0) else {
                skippedEmpty += 1
                continue
            }
            let text = String(cString: itemCStr)
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else {
                skippedEmpty += 1
                continue
            }
            if existing.contains(trimmed) {
                skippedDup += 1
                continue
            }

            // Alfred stores ts as CFAbsoluteTime (seconds since 2001-01-01).
            let ts = sqlite3_column_double(stmt, 1)
            let capturedAt = Date(timeIntervalSinceReferenceDate: ts)
            if capturedAt < cutoff {
                skippedRetention += 1
                continue
            }

            let app = sqlite3_column_text(stmt, 2).map { String(cString: $0) }

            existing.insert(trimmed)
            imported.append(ClipboardItem(
                id: UUID(), text: trimmed, capturedAt: capturedAt,
                pinned: false, sourceApp: app
            ))
        }

        Logger.shared.log(
            "Alfred import (text): read \(rowsRead) rows. " +
            "imported=\(imported.count) skippedDup=\(skippedDup) " +
            "skippedRetention=\(skippedRetention) skippedEmpty=\(skippedEmpty)"
        )

        // Image rows: Alfred stores them in clipboard.alfdb.data/<hash>.tiff
        // with metadata in SQLite where dataType = 1. Convert each to PNG,
        // save to our own image store, and create ClipboardItem entries.
        let imgImported = importAlfredImages(
            db: db,
            limit: limit,
            cutoff: cutoff,
            home: home
        )

        let preMergeCount = items.count
        let allImported = imported + imgImported
        items = (items + allImported).sorted { $0.capturedAt > $1.capturedAt }
        let postMergeCount = items.count
        persist()
        Logger.shared.log(
            "Alfred import: items \(preMergeCount) → \(postMergeCount) " +
            "(text +\(imported.count), images +\(imgImported.count)). Persisted to disk."
        )
        return AlfredImportResult(
            imported: imported.count + imgImported.count,
            skipped: skippedDup + skippedRetention + skippedEmpty,
            errorMessage: nil
        )
    }

    /// Pull image clips out of Alfred's SQLite store and copy the
    /// underlying .tiff sidecars into our own image folder, converting
    /// to PNG so they match the rest of our pipeline.
    private func importAlfredImages(
        db: OpaquePointer?,
        limit: Int,
        cutoff: Date,
        home: URL
    ) -> [ClipboardItem] {
        let alfredDataDir = home.appendingPathComponent(
            "Library/Application Support/Alfred/Databases/clipboard.alfdb.data"
        )

        let sql = "SELECT ts, app, dataHash FROM clipboard WHERE dataType = 1 ORDER BY ts DESC LIMIT ?"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else {
            Logger.shared.log("Alfred import (images): prepare failed")
            return []
        }
        defer { sqlite3_finalize(stmt) }
        sqlite3_bind_int(stmt, 1, Int32(limit))

        var imported: [ClipboardItem] = []
        var skippedRetention = 0
        var skippedMissing = 0
        var skippedDecode = 0
        var rowsRead = 0

        while sqlite3_step(stmt) == SQLITE_ROW {
            rowsRead += 1
            let ts = sqlite3_column_double(stmt, 0)
            let capturedAt = Date(timeIntervalSinceReferenceDate: ts)
            if capturedAt < cutoff { skippedRetention += 1; continue }

            guard let hashCStr = sqlite3_column_text(stmt, 2) else { continue }
            let hash = String(cString: hashCStr)
            // `dataHash` already carries the `.tiff` suffix in Alfred's
            // schema (`8746791...tiff`). The original code appended another
            // ".tiff", producing `...tiff.tiff`, which is never a real
            // file — so all 1,640 image rows were silently skipped as
            // "missing". Strip any existing extension to be safe.
            let filenameOnly = hash.hasSuffix(".tiff") ? hash : "\(hash).tiff"
            let alfredImageURL = alfredDataDir.appendingPathComponent(filenameOnly)

            guard let tiffData = try? Data(contentsOf: alfredImageURL),
                  let rep = NSBitmapImageRep(data: tiffData) else {
                skippedMissing += 1
                continue
            }

            guard let pngData = rep.representation(using: .png, properties: [:]) else {
                skippedDecode += 1
                continue
            }

            // Cap at our normal max image size (matches the polling path).
            guard pngData.count <= maxImageBytes else {
                skippedDecode += 1
                continue
            }

            let filename = "\(UUID().uuidString).png"
            let ourURL = imagesFolderURL.appendingPathComponent(filename)
            do {
                try pngData.write(to: ourURL, options: .atomic)
            } catch {
                skippedDecode += 1
                continue
            }

            let app = sqlite3_column_text(stmt, 1).map { String(cString: $0) }
            let thumbnail = Self.makeThumbnail(data: pngData, maxDimension: 128) ?? Data()
            let img = ClipboardImage(
                filename: filename,
                width: rep.pixelsWide,
                height: rep.pixelsHigh,
                bytes: pngData.count,
                thumbnail: thumbnail
            )
            imported.append(ClipboardItem(
                id: UUID(),
                text: "",
                capturedAt: capturedAt,
                pinned: false,
                sourceApp: app,
                image: img
            ))
        }

        Logger.shared.log(
            "Alfred import (images): read \(rowsRead) rows. " +
            "imported=\(imported.count) skippedRetention=\(skippedRetention) " +
            "skippedMissing=\(skippedMissing) skippedDecode=\(skippedDecode)"
        )
        return imported
    }

    // MARK: - Persistence

    private func loadFromDisk() {
        guard let data = try? Data(contentsOf: storeURL) else { return }
        // Try binary plist first (the format persist() now writes). Fall
        // back to JSON so a store written by an older Katib still loads
        // on first run after upgrade — next persist rewrites as plist.
        let decoded: [ClipboardItem]?
        if let plist = try? PropertyListDecoder().decode([ClipboardItem].self, from: data) {
            decoded = plist
        } else if let json = try? JSONDecoder().decode([ClipboardItem].self, from: data) {
            decoded = json
        } else {
            decoded = nil
        }
        guard let decoded else { return }
        items = decoded
        let preCount = items.count
        // Apply retention + capacity invariants on load.
        evictExpiredItems()
        let postEvict = items.count
        trimToCapacity()
        let postTrim = items.count

        // Sanity guard via the pure helper (so it's testable): if load
        // would discard more than half the on-disk items, REFUSE to
        // persist the trim. Catches init-order bugs (capacity not yet
        // pulled from settings ⇒ default value ⇒ destroys the file)
        // before they overwrite a healthy file. v1.30.3 shipped without
        // this guard and burned 7984 items.
        if Self.loadSafetyTripped(loadedCount: preCount, postTrimCount: postTrim) {
            Logger.shared.log(
                "Clipboard: SAFETY guard tripped — load would trim \(preCount) → \(postTrim), " +
                "refusing to persist. Check capacity (\(capacity)) and retention. " +
                "On-disk file UNCHANGED."
            )
            // Restore in-memory items to the as-loaded state (don't show a
            // truncated UI either — better to show everything until the
            // user explicitly accepts the trim by raising capacity then
            // copying something).
            items = decoded
            return
        }

        if postTrim != preCount {
            Logger.shared.log(
                "Clipboard: loaded \(preCount), evict→\(postEvict), trim→\(postTrim). Persisting."
            )
            persist()
        } else {
            Logger.shared.log("Clipboard: loaded \(items.count) items from disk")
        }
    }

    /// Serial queue for off-main disk writes. At 8k items the full-file
    /// encode+write is ~30-80ms; blocking main during a copy produced a
    /// visible hitch while typing in other apps.
    private static let persistQueue = DispatchQueue(
        label: "com.sevensevensix.katib.clipboard.persist",
        qos: .utility
    )
    /// Pending write-scheduled flag — coalesces bursty copies into one
    /// disk write per ~400ms. User-copying-multiple-things-rapidly hits
    /// one write instead of N writes.
    private var persistPending = false
    private let persistDebounce: TimeInterval = 0.4

    private func persist() {
        if persistPending { return }
        persistPending = true
        // Schedule on main so we can safely snapshot `items`, then hop to
        // the persist queue to do the encode + atomic write off-main.
        Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(self?.persistDebounce ?? 0.4 * 1_000_000_000))
            guard let self else { return }
            self.persistPending = false
            let snapshot = self.items
            let targetURL = self.storeURL
            Self.persistQueue.async {
                Self.writeSnapshot(snapshot, to: targetURL)
            }
        }
    }

    /// Immediate synchronous persist — bypass the debounce. Used by
    /// paths that absolutely need the write committed before returning
    /// (test teardown, explicit user "clear", etc.). Still off-main.
    private func persistImmediate() {
        persistPending = false
        let snapshot = items
        let targetURL = storeURL
        Self.persistQueue.sync {
            Self.writeSnapshot(snapshot, to: targetURL)
        }
    }

    nonisolated private static func writeSnapshot(_ items: [ClipboardItem], to url: URL) {
        // Binary plist — 5-10× faster encode than JSONEncoder, ~40%
        // smaller output. Decoder in loadFromDisk tries plist first, JSON
        // second so existing on-disk JSON files are still readable on
        // first boot after upgrade (one-way migration).
        let encoder = PropertyListEncoder()
        encoder.outputFormat = .binary
        guard let data = try? encoder.encode(items) else { return }
        try? data.write(to: url, options: .atomic)
    }
}

public struct ClipboardItem: Identifiable, Codable, Equatable, Sendable {
    public let id: UUID
    public let text: String
    public var capturedAt: Date
    public var pinned: Bool
    public var sourceApp: String?
    /// Bundle identifier of the app that owned the clipboard when this
    /// clip was captured. Optional — old clips persisted before this
    /// field was added decode with `nil`. Used by the picker UI to render
    /// the source app's icon as the row glyph (Maccy convention).
    public var sourceBundleID: String?
    /// When set, this clip is an image. `text` may still be populated with
    /// a description (usually empty for clipboard captures).
    public var image: ClipboardImage?

    public init(id: UUID, text: String, capturedAt: Date, pinned: Bool = false, sourceApp: String? = nil, sourceBundleID: String? = nil, image: ClipboardImage? = nil) {
        self.id = id
        self.text = text
        self.capturedAt = capturedAt
        self.pinned = pinned
        self.sourceApp = sourceApp
        self.sourceBundleID = sourceBundleID
        self.image = image
    }

    public var isImage: Bool { image != nil }

    /// Preview truncated to one line for the popover list. Image rows get a
    /// synthetic dimension label instead.
    public var preview: String {
        if let image {
            return "Image · \(image.width)×\(image.height) · \(Self.formatBytes(image.bytes))"
        }
        let single = text.replacingOccurrences(of: "\n", with: " ")
        return single.count > 80 ? String(single.prefix(80)) + "…" : single
    }

    private static func formatBytes(_ n: Int) -> String {
        ByteCountFormatter.string(fromByteCount: Int64(n), countStyle: .file)
    }
}

public struct ClipboardImage: Codable, Equatable, Sendable {
    /// File inside `~/Library/Application Support/VoiceTools/clipboard-images/`.
    /// Just the filename — controller reconstructs the full path so the store
    /// is portable across users/machines.
    public let filename: String
    public let width: Int
    public let height: Int
    public let bytes: Int
    /// Inline PNG thumbnail (~128px). Kept in JSON so list scrolling doesn't
    /// hit disk per row.
    public let thumbnail: Data

    public init(filename: String, width: Int, height: Int, bytes: Int, thumbnail: Data) {
        self.filename = filename
        self.width = width
        self.height = height
        self.bytes = bytes
        self.thumbnail = thumbnail
    }
}
